package net.civeira.phylax.features.oauth.userinvitation.infrastructure.driven;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;
import java.sql.SQLIntegrityConstraintViolationException;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.Optional;
import java.util.UUID;

import javax.sql.DataSource;

import jakarta.enterprise.context.ApplicationScoped;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import net.civeira.phylax.common.crypto.PasswordHasher;
import net.civeira.phylax.features.oauth.userinvitation.domain.InvitationRecord;
import net.civeira.phylax.features.oauth.userinvitation.domain.gateway.InvitationAcceptGateway;

/**
 * Accepts an invitation over {@code access_user_invitation} and {@code access_user} (task 2.2).
 *
 * <p>
 * One transaction: the invitation row is locked ({@code FOR UPDATE}), checked to be pending and
 * unexpired, the user is created (enabled, accepted, with the invitee address verified by the link)
 * and the invitation marked accepted by that user. Of two concurrent acceptances only the first
 * finds it pending; an existing account with the same name ({@code UK_USER_TENANT_NAME}) refuses
 * the acceptance. The roles stored in the invitation are not applied: they are for the
 * administrator to grant.
 */
@Slf4j
@ApplicationScoped
@RequiredArgsConstructor
public class InvitationAcceptAdapter implements InvitationAcceptGateway {

  private final DataSource source;
  private final PasswordHasher passwordHasher;

  @Override
  public Optional<String> acceptAndCreateUser(String invitationUid, String password) {
    // The (slow) password hash is computed before taking the row lock.
    String passwordHash = passwordHasher.hash(password);
    try (Connection conn = source.getConnection()) {
      boolean autoCommit = conn.getAutoCommit();
      conn.setAutoCommit(false);
      try {
        Optional<String> created = accept(conn, invitationUid, passwordHash);
        if (created.isPresent()) {
          conn.commit();
        } else {
          conn.rollback();
        }
        return created;
      } catch (SQLIntegrityConstraintViolationException ex) {
        conn.rollback();
        log.warn("Invitation {} not accepted: the account already exists", invitationUid);
        return Optional.empty();
      } catch (SQLException | RuntimeException ex) {
        conn.rollback();
        throw ex;
      } finally {
        conn.setAutoCommit(autoCommit);
      }
    } catch (SQLException ex) {
      if ("23000".equals(ex.getSQLState())) {
        return Optional.empty();
      }
      throw new IllegalStateException("Unable to accept an invitation", ex);
    }
  }

  private Optional<String> accept(Connection conn, String invitationUid, String passwordHash)
      throws SQLException {
    InvitationRecord invitation;
    try (PreparedStatement stat = conn.prepareStatement("SELECT " + InvitationLookupAdapter.COLUMNS
        + " FROM access_user_invitation WHERE uid = ? FOR UPDATE")) {
      stat.setString(1, invitationUid);
      try (ResultSet rs = stat.executeQuery()) {
        if (!rs.next()) {
          return Optional.empty();
        }
        invitation = InvitationLookupAdapter.read(rs);
      }
    }
    if (!invitation.open(Instant.now())) {
      return Optional.empty();
    }
    String userUid = UUID.randomUUID().toString();
    try (PreparedStatement stat = conn.prepareStatement("INSERT INTO access_user (uid, version,"
        + " approve, email, email_verified, enabled, name, password, temporal_password,"
        + " use_second_factors, tenant) VALUES (?, 0, 'ACCEPTED', ?, 1, 1, ?, ?, 0, 0, ?)")) {
      stat.setString(1, userUid);
      stat.setString(2, invitation.email());
      stat.setString(3, invitation.email());
      stat.setString(4, passwordHash);
      stat.setString(5, invitation.tenantUid());
      stat.execute();
    }
    try (PreparedStatement stat = conn.prepareStatement("UPDATE access_user_invitation"
        + " SET status = 'ACCEPTED', accepted_at = ?, accepted_by = ?, version = version + 1"
        + " WHERE uid = ? AND status = 'PENDING'")) {
      stat.setTimestamp(1, Timestamp.from(Instant.now()));
      stat.setString(2, userUid);
      stat.setString(3, invitationUid);
      if (stat.executeUpdate() != 1) {
        return Optional.empty();
      }
    }
    return Optional.of(userUid);
  }
}
